text:
{
  "units": [
    {
      "issue": {
        "id": "U01",
        "role": "共同前提",
        "statement": "确定本虚构情景的规范适用版本及结算边界"
      },
      "decisive_facts": [
        {
          "fact": "相关借款及保证均成立于2022年；案件于2023-08-01新受理。",
          "spans": ["normalized_text引言", "S01", "S03", "S06", "S07", "S10"]
        },
        {
          "fact": "计息截至2023-08-01但不计当日；最终余额须反映当日SP-01到账后的清偿结果。",
          "spans": ["normalized_text引言", "S13"]
        },
        {
          "fact": "全部文件和主体关系属于显著标明的虚构题设，不存在可提取的实际法院判断。",
          "spans": ["normalized_text引言"]
        }
      ],
      "support_spans": [
        {
          "span": "normalized_text引言",
          "excerpt": "这是法律数据合成研究构造的闭卷情景，不是真实诉讼、证据或判决。"
        },
        {
          "source_id": "lending-2020-12",
          "provisions": ["31"],
          "url": "https://cicc.court.gov.cn/html/1/380/385/12844.html",
          "basis": "施行后新受理的一审民间借贷案件适用该规定；题设借款不属于2020-08-20之前成立的借款。"
        },
        {
          "source_id": "civil-code-2020",
          "provisions": ["1260"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html",
          "basis": "民法典自2021-01-01施行。"
        },
        {
          "source_id": "guarantee-2020",
          "provisions": ["25", "31", "32", "34"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/282721.html",
          "basis": "材料标注该解释自2021-01-01施行，所涉保证成立及程序事件均在其后。"
        }
      ],
      "dependencies": [],
      "answerability": {
        "status": "supported_on_supplied_record",
        "supported_states": [
          "按所附2021年起施行的规范处理本情景。",
          "2015年版本中的高利转贷及借款人知情条件不能移用于A。",
          "计息截止与SP-01清偿入账必须分别处理。"
        ],
        "basis": "合同成立、程序事件和结算时点均有明确题设，不需要建立跨旧法期间的利息分段。"
      }
    },
    {
      "issue": {
        "id": "U02",
        "role": "金额与责任分支",
        "statement": "A借款效力、实际财产返还范围及丁的保证合同责任"
      },
      "decisive_facts": [
        {
          "fact": "甲将套取的银行信贷资金转贷给乙；乙事先不知来源，约定利率为6%。",
          "spans": ["S01"]
        },
        {
          "fact": "票面160000元，实际交付142970.00元；另有同一到账交易号的收据。",
          "spans": ["S01", "S02"]
        },
        {
          "fact": "乙已返还20100.00元；双方约定如合同无效，该款全部冲抵应返还财产。",
          "spans": ["S02"]
        },
        {
          "fact": "丁提供连带保证；甲仅请求剩余实际财产返还及保证合同项下支付，不请求保证合同无效后的过错赔偿。",
          "spans": ["S01", "S02", "S12"]
        }
      ],
      "support_spans": [
        {
          "span": "S01",
          "excerpt": "甲把为个人消费用途向银行套取的信贷资金转给乙，银行追踪与双方陈述已证实该来源。"
        },
        {
          "span": "S02",
          "excerpt": "如A被认定无效，双方同意在清算中全部作为已返还财产冲抵"
        },
        {
          "source_id": "lending-2020-12",
          "provisions": ["13"],
          "url": "https://cicc.court.gov.cn/html/1/380/385/12844.html",
          "basis": "套取金融机构贷款转贷属于合同无效情形，条文不以高利或借款人事先知情为条件。"
        },
        {
          "source_id": "civil-code-2020",
          "provisions": ["157", "682"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html",
          "basis": "无效后返还实际取得的财产；主合同无效原则上导致保证合同无效，过错责任属于另行判断事项。"
        }
      ],
      "dependencies": [
        {
          "unit": "U01",
          "relation": "规范版本决定A的无效要件"
        }
      ],
      "answerability": {
        "status": "supported_on_supplied_record",
        "supported_states": [
          "A借款合同无效。",
          "返还范围以142970.00元实际交付减去20100.00元已返还款确定，不重复计算同号收据。",
          "丁的保证合同无效，不能支持本次依保证合同立即支付的请求；不据此推断其不存在任何可能的过错责任。"
        ],
        "basis": "资金来源、实际交付及附条件清算约定均明确；保证无效后的赔偿不在本次请求范围内。"
      }
    },
    {
      "issue": {
        "id": "U03",
        "role": "金额分支",
        "statement": "B的实际本金、合法结息本金及整体本息上限"
      },
      "decisive_facts": [
        {
          "fact": "B于2022-01-12实际交付并成立；票面195990.00元中预扣12290.00元，实际到账183700.00元。",
          "spans": ["S03"]
        },
        {
          "fact": "合同年利率13.20%，成立时一年期LPR按题设为3.70%。",
          "spans": ["S03"]
        },
        {
          "fact": "2022-07-06、2022-10-17、2023-01-09三次结息记账均无新增交付；双方不另成立债务更新合同。",
          "spans": ["S04", "S05"]
        },
        {
          "fact": "各期沿用原利率和成立时LPR，按实际自然日/365计算，中间不取分；SP-01之前无其他还款。",
          "spans": ["S04", "S13"]
        },
        {
          "fact": "B经甲乙展期至2023-06-30，最终请求包括截至截日的全部可保护本息。",
          "spans": ["S06", "S12"]
        }
      ],
      "support_spans": [
        {
          "span": "S03",
          "excerpt": "乙于2022-01-12实际收到183700.00元，当日起息，合同也于该日成立。"
        },
        {
          "span": "S04",
          "excerpt": "双方不另成立债务更新合同，各期沿用最初借据约定的利率与合同成立时LPR。"
        },
        {
          "span": "S05",
          "excerpt": "B-1，2022-07-06，纸面本金208393.75元，新增交付0.00元。"
        },
        {
          "source_id": "civil-code-2020",
          "provisions": ["670", "679", "680"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html",
          "basis": "预扣利息以实际借款额确定本金；自然人借款以实际提供借款为成立条件，利率受法定限制。"
        },
        {
          "source_id": "lending-2020-12",
          "provisions": ["25", "26", "27", "28"],
          "url": "https://cicc.court.gov.cn/html/1/380/385/12844.html",
          "basis": "分别约束约定利率、实际本金、合法利息资本化、整个借款期间本息总额及逾期利息。"
        }
      ],
      "dependencies": [
        {
          "unit": "U01",
          "relation": "确定利率保护及结息适用规则"
        }
      ],
      "answerability": {
        "status": "supported_for_calculation",
        "supported_states": [
          "最初本金为183700.00元，利率保护上限为14.80%，约定13.20%未超过该上限。",
          "三张后续借据不构成三笔新增交付；无新增交付也不当然排除合法利息资本化。",
          "应按实际本金、约定利率及真实日数重建各次合法结息额，纸面金额中缺乏合法本息基础的部分不能直接继承。",
          "截日前可保护本息须比较合法逐次结息候选额与以最初本金按14.80%计算整个期间单利所得的整体上限。",
          "SP-01的最终归属由U07另行确定，不能先假定B获得该付款。"
        ],
        "basis": "本金、起息日、归档日、利率、计算基数和截止时点齐全；精确金额仍需逐段复算。",
        "calculation_checkpoints": [
          "183700.00元作为初始本金",
          "依次核对三个归档区间的日数与合法资本化金额",
          "核对最后归档日至截日的利息及逾期处理",
          "独立计算整体本息上限并比较",
          "仅在最终输出金额上取分"
        ]
      }
    },
    {
      "issue": {
        "id": "U04",
        "role": "保证状态分支",
        "statement": "B保证类型、展期对保证期间的影响及撤诉后的权利行使效果"
      },
      "decisive_facts": [
        {
          "fact": "戊承诺乙不履行到期债务时无条件清偿，无须甲先向乙追索。",
          "spans": ["S06"]
        },
        {
          "fact": "保证期间仅写至本息全部还清；原履行期限届满日为2023-01-12，戊未书面同意甲乙展期。",
          "spans": ["S06"]
        },
        {
          "fact": "甲于2023-07-05起诉戊，完整给付请求于07-07送达，07-09撤诉；撤诉不含放弃实体债权。",
          "spans": ["S06"]
        },
        {
          "fact": "戊书面同意合法结息机制，保证范围包括原B关系按法定限额清算的本息；后续催告发生于07-18。",
          "spans": ["S06"]
        }
      ],
      "support_spans": [
        {
          "span": "S06",
          "excerpt": "乙不履行到期B债务时，戊即无条件向甲清偿，无须甲先向乙追索"
        },
        {
          "span": "S06",
          "excerpt": "起诉状副本2023-07-07送达戊，送达内容包括完整给付请求；甲2023-07-09撤诉"
        },
        {
          "source_id": "guarantee-2020",
          "provisions": ["25", "31", "32"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/282721.html",
          "basis": "依条款实质区分保证类型；还清为止的期间约定不明；连带保证诉状副本已在期间内送达的，撤诉不否定该次权利行使。"
        },
        {
          "source_id": "civil-code-2020",
          "provisions": ["688", "691", "692", "693", "695"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html",
          "basis": "规定连带保证请求、保证范围、六个月期间及未经保证人书面同意展期不影响保证期间。"
        }
      ],
      "dependencies": [
        {
          "unit": "U01",
          "relation": "确定保证规范版本"
        },
        {
          "unit": "U03",
          "relation": "确定保证请求可覆盖的合法B债务金额，不以纸面虚增金额扩张范围"
        }
      ],
      "answerability": {
        "status": "supported_on_supplied_record",
        "supported_states": [
          "戊提供连带责任保证，不因缺少类型标题而适用一般保证。",
          "保证期间以原到期日计算六个月，届满日为2023-07-12，不随未经书面同意的展期后移。",
          "07-07送达发生于保证期间内，之后撤诉不消除该次有效行权。",
          "截日B仍有戊的保证；在约定且合法的保证范围内，可请求戊立即承担连带清偿责任。"
        ],
        "basis": "保证条款、原到期日、展期同意状态及诉状送达均有明确记录，07-18催告不是维持责任的必要依据。"
      }
    },
    {
      "issue": {
        "id": "U05",
        "role": "证据归属与金额分支",
        "statement": "C付款去重、到账识别及各笔付款的内部抵充顺序"
      },
      "decisive_facts": [
        {
          "fact": "C于2022-02-07交付224100.00元，无预扣；借期及逾期年利率均为11.40%，实际自然日/365单利计算。",
          "spans": ["S07"]
        },
        {
          "fact": "1680元实现债权费用在全部付款前到期，题设明确依法可收取。",
          "spans": ["S07"]
        },
        {
          "fact": "T-01至T-06均已结算并指定清偿C，日期、金额分别列于流水主表。",
          "spans": ["S08"]
        },
        {
          "fact": "仅T-02有双方签署的本金优先补充协议；其他付款的还本金备注仅由乙单方作出。",
          "spans": ["S09"]
        },
        {
          "fact": "截图及收据中的T-01与主表首行同号；X-01已撤销且没有到账。",
          "spans": ["S11"]
        }
      ],
      "support_spans": [
        {
          "span": "S09",
          "excerpt": "仅适用于T-02的补充协议：该笔付款用于清偿本金，剩余依次偿付实现债权费用和利息。"
        },
        {
          "span": "S11",
          "excerpt": "两份记录的银行交易号均与S08首行相同。"
        },
        {
          "span": "S11",
          "excerpt": "X-01未执行，已撤销付款指令，未向甲账户记入该金额。"
        },
        {
          "source_id": "civil-code-2020",
          "provisions": ["560", "561"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html",
          "basis": "具体债务的指定与该债务内部费用、利息、本金的抵充顺序应分别判断；内部顺序原则上为费用、利息、本金，但允许双方另约。"
        },
        {
          "source_id": "lending-2020-12",
          "provisions": ["25", "28"],
          "url": "https://cicc.court.gov.cn/html/1/380/385/12844.html",
          "basis": "借期与逾期约定利率均须受成立时一年期LPR四倍限制。"
        }
      ],
      "dependencies": [
        {
          "unit": "U01",
          "relation": "确定适用清偿及利率规则"
        }
      ],
      "answerability": {
        "status": "supported_for_calculation",
        "supported_states": [
          "T-01只计一次，X-01不构成清偿。",
          "T-02依双方协议先抵本金；其他T系列付款按费用、利息、本金顺序抵充。",
          "乙单方还本金备注不能替代双方关于内部抵充顺序的约定。",
          "每笔付款前累计应计利息，付款后按剩余本金继续单利计息，不对未付利息另计息。",
          "可据此建立SP-01到账前的C本金、利息、费用余额。"
        ],
        "basis": "执行状态、交易号、付款指向、双方协议及计息规则均充分；提交付款指令的单方主张不改变银行未执行事实。",
        "calculation_checkpoints": [
          "逐笔核对T系列日期和金额",
          "分开维护本金、未付利息和费用余额",
          "付款当日不再对已偿还本金计息",
          "保留T-02本金优先造成的后续计息基数变化"
        ]
      }
    },
    {
      "issue": {
        "id": "U06",
        "role": "保证状态分支",
        "statement": "C一般保证的期间行权、撤诉再诉及收件签名效果"
      },
      "decisive_facts": [
        {
          "fact": "己仅在乙不能履行、无力偿还时承担责任，未另约保证期间；C于2022-12-15到期。",
          "spans": ["S07", "S10"]
        },
        {
          "fact": "甲于2023-06-08起诉乙，06-12撤诉，06-20再诉；再诉截至截日尚未审判。",
          "spans": ["S10"]
        },
        {
          "fact": "05-08仅向己催告；06-25己仅确认收件并明确不确认付款义务，没有新的协商或保证承诺。",
          "spans": ["S10"]
        },
        {
          "fact": "己已主张不再承担保证责任；乙有可执行财产，无先诉抗辩例外，己未放弃先诉抗辩。",
          "spans": ["S10"]
        }
      ],
      "support_spans": [
        {
          "span": "S10",
          "excerpt": "乙不能履行C债务、无力偿还时，己才代为向甲清偿"
        },
        {
          "span": "S10",
          "excerpt": "甲2023-06-12撤诉，法院同日准许；程序档案C-诉2：甲2023-06-20重新对乙起诉C债务"
        },
        {
          "span": "S10",
          "excerpt": "收到，不确认付款义务"
        },
        {
          "source_id": "civil-code-2020",
          "provisions": ["687", "692", "693"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html",
          "basis": "一般保证与先诉抗辩有别于保证期间；一般保证须在期间内对债务人诉讼或仲裁。"
        },
        {
          "source_id": "guarantee-2020",
          "provisions": ["25", "31", "34"],
          "url": "https://www.court.gov.cn/zixun/xiangqing/282721.html",
          "basis": "一般保证期间内起诉后撤诉，未于期间届满前再诉的，支持保证人不再承担责任；责任消灭后的签收不当然成立新保证。"
        }
      ],
      "dependencies": [
        {
          "unit": "U01",
          "relation": "确定保证期间与撤诉规则"
        }
      ],
      "answerability": {
        "status": "supported_on_supplied_record",
        "supported_states": [
          "己提供一般保证，保证期间届满日为2023-06-15。",
          "首次起诉后撤诉，06-20再诉已超过保证期间，05-08向己催告不能替代一般保证所需行权方式。",
          "原保证责任消灭，06-25单纯收件签名未形成新的保证合同。",
          "截日C不能再按原保证计为有担保债务；己不承担本次请求的保证合同支付责任。",
          "责任消灭是本分支的决定性状态，不能仅表述为暂有先诉抗辩。"
        ],
        "basis": "撤诉、再诉、期间届满及签收内容均明确；无须推定未披露的新保证或行权事件。"
      }
    },
    {
      "issue": {
        "id": "U07",
        "role": "跨分支依赖",
        "statement": "SP-01在B、C之间的债务抵充及C内部清偿"
      },
      "decisive_facts": [
        {
          "fact": "SP-01为2023-08-01独立到账的25000.00元，仅用于B、C，不用于A。",
          "spans": ["S13"]
        },
        {
          "fact": "乙未在B、C之间指定，双方也未约定二者之间的抵充顺序。",
          "spans": ["S13"]
        },
        {
          "fact": "B展期至2023-06-30，C于2022-12-15到期；两笔在付款时均已到期。",
          "spans": ["S06", "S07", "S13"]
        },
        {
          "fact": "B、C均无各自保证合同以外的抵押、质押或其他担保。",
          "spans": ["S13"]
        }
      ],
      "support_spans": [
        {
          "span": "S13",
          "excerpt": "双方书面约定该款只用于清偿B、C两笔借款，不用于A返还债务"
        },
